import React,{useState} from 'react';
import {activitiesOf} from './programme.js';
import {supportActivity,emptySupport} from './support-model.js';
const SELF={'revisit':'I need to reread the source','explain-again':'I want to explain it again','ready-to-practise':'I am ready for another practice attempt'};
export function GuidedSupport({pack,unit,activityKey,onActivity,save,busy,onBack}){
 const activities=activitiesOf(pack),a=supportActivity(pack,activityKey),s=unit.support?.find(s=>s.key===activityKey)||emptySupport(activityKey);
 const [thought,setThought]=useState(s.thought||''),[teachBack,setTeachBack]=useState(s.teachBack),[reveal,setReveal]=useState(false);
 const started=s.thought!==null||s.skipped,shown=a.sources.filter(p=>s.sourceIds.includes(p.id));
 const act=action=>save({...action,key:a.key});
 return <section className="support-notebook surface" aria-labelledby="support-title"><div className="support-toolbar"><button className="text-button" onClick={onBack}>Back to my programme</button><span>Reviewed guided help</span></div><h2 id="support-title">Work through the idea.</h2><p>Put your thinking beside the evidence. This guide uses the chapter’s reviewed content; it does not write or grade your answer.</p><p className="subtle">Choose any activity in this chapter. Your route uses support for the activities in your programme’s selected focus.</p><label>Activity<select value={activityKey} onChange={e=>onActivity(e.target.value)} disabled={busy}>{activities.map(x=><option key={x.key} value={x.key}>{x.label}</option>)}</select></label><div className="support-focus"><h3>{a.prompt}</h3>{a.context&&<p className="support-context">{a.context}</p>}<p>{a.scope}</p></div>{!a.hasEvidence?<p role="alert">This activity has no reviewed supporting passage. Add and review material before using guided help.</p>:<>
 <section className="support-step"><h3>Start with your own thinking.</h3>{started?<><p className="support-caption">Your first thought, preserved</p><blockquote><p>{s.skipped?'Not sure yet — a valid place to begin.':s.thought}</p></blockquote></>:<><label>My first thought<textarea rows={4} maxLength={1200} value={thought} onChange={e=>setThought(e.target.value)} placeholder="What do you think is happening, and why?"/></label><div className="form-actions"><button disabled={busy||!thought.trim()} onClick={()=>act({type:'support-thought',text:thought})}>Save my first thought</button><button disabled={busy} onClick={()=>act({type:'support-thought',skip:true})}>I’m not sure yet</button></div></>}</section>
 {started&&<><section className="support-step"><h3>Take one useful clue.</h3>{s.clue?<div className="support-clue"><p>{a.hint||'Look for the relationship described in the question. Choose one supporting passage below and identify the detail that helps explain it.'}</p><p className="subtle">{a.hint?'A hint from this reviewed chapter.':'A reading prompt, not an additional subject fact.'}</p></div>:<><p>Try a small prompt before opening the full explanation.</p><button disabled={busy} onClick={()=>act({type:'support-clue'})}>Show a clue</button></>}</section>
 <section className="support-step"><h3>Choose the evidence that helps.</h3><p>Open a passage, then explain which detail supports your thinking. Opening evidence records that you used support.</p><div className="support-source-tabs">{a.sources.map(p=><button key={p.id} disabled={busy||s.sourceIds.includes(p.id)} onClick={()=>act({type:'support-source',sourceId:p.id})}>{s.sourceIds.includes(p.id)?'Opened: ':'Read: '}{p.title} — {p.locator}</button>)}</div>{shown.map(p=><blockquote key={p.id}><p>{p.excerpt}</p><cite>{p.title} — {p.locator}</cite></blockquote>)}</section>
 {!!shown.length&&<><section className="support-step"><h3>Compare when you are ready.</h3>{a.explanation?<>{s.compared?<div className="support-comparison"><p className="support-caption">Reviewed explanation</p><p>{a.explanation}</p><p className="subtle">Compare the reasoning with the source above. This is the chapter’s explanation, not an evaluation of your writing.</p></div>:<><p>You can keep the explanation hidden and try another answer first. Opening it may reveal the answer.</p>{reveal?<div className="form-actions"><button disabled={busy} onClick={()=>act({type:'support-compare'})}>Open the reviewed explanation</button><button onClick={()=>setReveal(false)}>Keep it hidden</button></div>:<button onClick={()=>setReveal(true)}>I’m ready to compare</button>}</>}</>:<p>This activity has no separate reviewed explanation. Use its source to compare the relationships and trade-offs; this guide will not invent a model answer.</p>}</section>
 <section className="support-step"><h3>Explain it again, in your words.</h3><p>Name a detail from the passage, connect it to the question, and say what you changed or still find uncertain.</p><label>My explanation after checking the source<textarea rows={5} maxLength={1600} value={teachBack} onChange={e=>setTeachBack(e.target.value)}/></label><button className="primary" disabled={busy||!teachBack.trim()} onClick={()=>act({type:'support-teachback',text:teachBack})}>Save my explanation</button>{s.teachBack&&<><p className="subtle">Saved, ungraded. Word count and completion do not measure understanding.</p><fieldset><legend>What would help next?</legend>{Object.entries(SELF).map(([value,label])=><label className="check" key={value}><input type="radio" name="support-selfcheck" checked={s.selfCheck===value} disabled={busy} onChange={()=>act({type:'support-selfcheck',value})}/>{label}</label>)}</fieldset><p className="subtle">This is your self-check. It does not change a grade or unlock a level.</p></>}</section></>}
 </>}
 </>}</section>;
}
